using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Coordinates;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Events;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Measurements;
namespace Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Events;
internal abstract class EventRuleBase: AstronomyKnowledgeValidationRule<AstronomyEventPayload>{protected static AstronomyKnowledgeValidationIssue Issue(string c,string m,string p,string r)=>new(c,AstronomyKnowledgeValidationSeverity.Error,m,p,r,AstronomyKnowledgeDomain.Event,AstronomyKnowledgePayloadFamily.AstronomicalEvent); public override AstronomyKnowledgeDomain Domain=>AstronomyKnowledgeDomain.Event; public override AstronomyKnowledgePayloadFamily Family=>AstronomyKnowledgePayloadFamily.AstronomicalEvent;}
public sealed class AstronomyEventAggregateValidationRule:EventRuleBase{public const string Id="event.aggregate.integrity"; public override string RuleId=>Id; public override int Order=>100; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyEventPayload p,AstronomyKnowledgeValidationContext c){var e=p.Event; if(!Enum.IsDefined(e.Kind)) yield return Issue(AstronomyEventValidationCodes.EventKindInvalid,"Event kind must be defined.","$.event.kind",RuleId); if(!Enum.IsDefined(e.Significance)) yield return Issue(AstronomyEventValidationCodes.SignificanceInvalid,"Event significance must be defined.","$.event.significance",RuleId); if(c.Mode==AstronomyKnowledgeValidationMode.Strict&&(string.IsNullOrWhiteSpace(e.Name)||string.IsNullOrWhiteSpace(e.Summary))) yield return Issue(AstronomyEventValidationCodes.TextIncomplete,"Strict event validation requires name and summary.","$.event",RuleId);}}
public sealed class AstronomyEventTemporalExtentValidationRule:EventRuleBase{public const string Id="event.temporal.extent"; public override string RuleId=>Id; public override int Order=>200; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyEventPayload p,AstronomyKnowledgeValidationContext c){switch(p.Event.TemporalExtent){case AstronomyInstantEventTemporalExtent i: if(i.Kind is not (AstronomyEventTimeKind.Instant or AstronomyEventTimeKind.ApproximateInstant)) yield return Issue(AstronomyEventValidationCodes.TemporalKindMismatch,"Instant extent kind mismatch.","$.event.temporalExtent.kind",RuleId); if(i.InstantUtc.Offset!=TimeSpan.Zero) yield return Issue(AstronomyEventValidationCodes.TemporalUtcInvalid,"Instant must use UTC.","$.event.temporalExtent.instantUtc",RuleId); break; case AstronomyIntervalEventTemporalExtent v: if(v.Kind is not (AstronomyEventTimeKind.Interval or AstronomyEventTimeKind.ApproximateInterval)) yield return Issue(AstronomyEventValidationCodes.TemporalKindMismatch,"Interval extent kind mismatch.","$.event.temporalExtent.kind",RuleId); if(v.StartUtc.Offset!=TimeSpan.Zero||v.EndUtc.Offset!=TimeSpan.Zero) yield return Issue(AstronomyEventValidationCodes.TemporalUtcInvalid,"Interval endpoints must use UTC.","$.event.temporalExtent",RuleId); if(v.StartUtc>v.EndUtc) yield return Issue(AstronomyEventValidationCodes.TemporalOrderingInvalid,"Interval start cannot be after end.","$.event.temporalExtent",RuleId); break; default: yield return Issue(AstronomyEventValidationCodes.TemporalKindMismatch,"Temporal extent runtime type is unsupported.","$.event.temporalExtent",RuleId); break;}}}
public sealed class AstronomyEventReferenceContextValidationRule:EventRuleBase{public const string Id="event.reference-context.compatibility"; public override string RuleId=>Id; public override int Order=>300; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyEventPayload p,AstronomyKnowledgeValidationContext c){var r=p.Event.ReferenceContext; var ok=r.Scope switch{AstronomyEventScope.Global=>r.ReferenceFrame is null&&r.ReferenceOrigin is null&&r.CoordinateSystem is null, AstronomyEventScope.ReferenceFrameSpecific=>r.ReferenceFrame.HasValue&&r.ReferenceOrigin.HasValue&&r.CoordinateSystem.HasValue, AstronomyEventScope.ObserverSpecific=>r.ObservationContext is not null, _=>true}; if(!ok) yield return Issue(AstronomyEventValidationCodes.ReferenceContextIncompatible,"Event reference context is incompatible with its scope/frame/origin/coordinate combination.","$.event.referenceContext",RuleId);}}
public sealed class AstronomyEventParticipantValidationRule:EventRuleBase{public const string Id="event.participants.identity"; public override string RuleId=>Id; public override int Order=>400; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyEventPayload p,AstronomyKnowledgeValidationContext c){var parts=p.Event.Participants; if(parts.GroupBy(x=>(x.Entity.EntityId,x.Role)).Any(g=>g.Count()>1)) yield return Issue(AstronomyEventValidationCodes.ParticipantDuplicate,"Participants must be unique by entity reference and role.","$.event.participants",RuleId); if(parts.Any(x=>!Enum.IsDefined(x.Role))) yield return Issue(AstronomyEventValidationCodes.ParticipantRoleInvalid,"Participant role must be defined.","$.event.participants",RuleId); var primary=parts.Count(x=>x.Role==AstronomyEventParticipantRole.Primary); if(primary!=1) yield return Issue(AstronomyEventValidationCodes.ParticipantPrimaryInvalid,"Exactly one primary participant is required.","$.event.participants",RuleId);}}
public sealed class AstronomyEventPhaseMarkerValidationRule:EventRuleBase{public const string Id="event.phase-markers.identity"; public override string RuleId=>Id; public override int Order=>500; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyEventPayload p,AstronomyKnowledgeValidationContext c){var a=p.Event.PhaseMarkers; if(a.GroupBy(x=>(x.Kind,x.TimeUtc)).Any(g=>g.Count()>1)) yield return Issue(AstronomyEventValidationCodes.PhaseMarkerDuplicate,"Phase markers must be unique by kind and instant.","$.event.phaseMarkers",RuleId); if(!a.SequenceEqual(a.OrderBy(x=>x.TimeUtc).ThenBy(x=>x.Kind))) yield return Issue(AstronomyEventValidationCodes.PhaseMarkerOrderingInvalid,"Phase markers must be chronological.","$.event.phaseMarkers",RuleId); foreach(var m in a){ if(m.TimeUtc.Offset!=TimeSpan.Zero) yield return Issue(AstronomyEventValidationCodes.PhaseMarkerUtcInvalid,"Phase marker instant must use UTC.","$.event.phaseMarkers",RuleId); if(!Contains(p.Event.TemporalExtent,m.TimeUtc)) yield return Issue(AstronomyEventValidationCodes.PhaseMarkerOutsideExtent,"Phase marker must fall within event extent.","$.event.phaseMarkers",RuleId);}} static bool Contains(AstronomyEventTemporalExtent e,DateTimeOffset t)=>e switch{AstronomyInstantEventTemporalExtent i=>t==i.InstantUtc,AstronomyIntervalEventTemporalExtent v=>t>=v.StartUtc&&t<=v.EndUtc,_=>false};}
public sealed class AstronomyEventGeometryValidationRule:EventRuleBase{public const string Id="event.geometry.catalog"; public override string RuleId=>Id; public override int Order=>600; static readonly Dictionary<AstronomyEventGeometryCategory,AstronomyMeasurementDimension[]> DimensionCatalog=new(){[AstronomyEventGeometryCategory.AngularSeparation]=[AstronomyMeasurementDimension.Angle],[AstronomyEventGeometryCategory.PositionAngle]=[AstronomyMeasurementDimension.Angle],[AstronomyEventGeometryCategory.Distance]=[AstronomyMeasurementDimension.Distance],[AstronomyEventGeometryCategory.Obscuration]=[AstronomyMeasurementDimension.Percentage,AstronomyMeasurementDimension.Dimensionless],[AstronomyEventGeometryCategory.Magnitude]=[AstronomyMeasurementDimension.Magnitude],[AstronomyEventGeometryCategory.Phase]=[AstronomyMeasurementDimension.Dimensionless,AstronomyMeasurementDimension.Percentage],[AstronomyEventGeometryCategory.Alignment]=[AstronomyMeasurementDimension.Angle,AstronomyMeasurementDimension.Dimensionless],[AstronomyEventGeometryCategory.ShadowGeometry]=[AstronomyMeasurementDimension.Distance,AstronomyMeasurementDimension.Area,AstronomyMeasurementDimension.Angle],[AstronomyEventGeometryCategory.ContactGeometry]=[AstronomyMeasurementDimension.Time,AstronomyMeasurementDimension.Angle],[AstronomyEventGeometryCategory.Other]=Enum.GetValues<AstronomyMeasurementDimension>()}; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyEventPayload p,AstronomyKnowledgeValidationContext c){var g=p.Event.Geometry; if(g.GroupBy(x=>(x.QuantityId,x.Category,x.Epoch)).Any(x=>x.Count()>1)) yield return Issue(AstronomyEventValidationCodes.GeometryDuplicate,"Geometry must be unique by quantity, category, and epoch.","$.event.geometry",RuleId); foreach(var q in g){ if(!Enum.IsDefined(q.Category)) yield return Issue(AstronomyEventValidationCodes.GeometryCategoryInvalid,"Geometry category must be defined.","$.event.geometry.category",RuleId); else if(!DimensionCatalog[q.Category].Contains(q.Measurement.Unit.Dimension)) yield return Issue(AstronomyEventValidationCodes.GeometryDimensionMismatch,"Geometry measurement dimension is incompatible with its category.","$.event.geometry.measurement",RuleId); foreach(var i in AstronomyEventMeasurementValidator.Validate(q.Measurement,"$.event.geometry.measurement",RuleId,Domain,Family)) yield return i; if(q.Epoch?.InstantUtc is { } dt && dt.Offset!=TimeSpan.Zero) yield return Issue(AstronomyEventValidationCodes.GeometryEpochInvalid,"Geometry epoch instant must use UTC.","$.event.geometry.epoch",RuleId);}}}
public sealed class AstronomyEventCircumstanceValidationRule:EventRuleBase{public const string Id="event.circumstances.identity"; public override string RuleId=>Id; public override int Order=>700; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyEventPayload p,AstronomyKnowledgeValidationContext c){if(p.Event.Circumstances.GroupBy(x=>x.CircumstanceId).Any(g=>g.Count()>1)) yield return Issue(AstronomyEventValidationCodes.CircumstanceDuplicate,"Circumstances must be unique by circumstance ID.","$.event.circumstances",RuleId);}}
